def resample_linear(data, positions):
    result = []
    n = len(data)
    for pos in positions:
        if pos < 0 or pos > n - 1:
            continue  # reject out-of-range positions
        if pos == int(pos):
            idx = int(pos)
            result.append(data[idx])
        else:
            idx = int(pos)
            if idx >= n - 1:
                result.append(data[-1])
            else:
                fraction = pos - idx
                value = data[idx] + fraction * (data[idx + 1] - data[idx])
                result.append(value)
    return result
